    const ports = new Set<string>();
    for (const f of [a, b]) {
      for (const url of [f.brokerUrl, f.proxyUrl, f.vaultUrl]) {
        assert.match(url, /^http:\/\/127\.0\.0\.1:\d+$/);
        ports.add(url);
      }
